// The teacher dashboard already parsed the CSV, matched students,
// computed scores, and wrote student_scores itself. All this workflow
// does is turn the two base64 CSVs it sends into binary attachments for
// the Gmail node below.
//
// Manually setting binary.<prop>.data to the raw base64 string does NOT
// decode it -- n8n writes that string out verbatim as the attachment's
// content. prepareBinaryData() is the only reliable way to hand n8n a
// real decoded Buffer, regardless of its binary-data storage mode.
const body = $json.body ?? $json;

const scoreBuffer = Buffer.from(body.scoreCsv.content, 'base64');
const attendanceBuffer = Buffer.from(body.attendanceCsv.content, 'base64');

const scoreBinary = await this.helpers.prepareBinaryData(scoreBuffer, body.scoreCsv.filename, 'text/csv');
const attendanceBinary = await this.helpers.prepareBinaryData(attendanceBuffer, body.attendanceCsv.filename, 'text/csv');

return [{
  json: {
    to: body.to,
    subject: body.subject,
    message: body.message,
  },
  binary: {
    scoreCsv: scoreBinary,
    attendanceCsv: attendanceBinary,
  },
}];
